// upsertBalanceTx writes the per-resource domain-table portion of a
// balance upsert inside an existing transaction. The caller is
// responsible for the generic resources insert (via upsertGenericResourceTx)
// and for committing the tx. Splitting this out lets UpsertBatch dispatch
// domain inserts per item without opening a per-item transaction.
func (s *Store) upsertBalanceTx(tx *sql.Tx, id string, obj map[string]any, data json.RawMessage) error {
	// e-Boekhouden's balance DTOs (GET /v1/ledger/balances and
	// GET /v1/ledger/{id}/balance) carry no ledgerId field at all — only
	// Code/Type/Balance, keyed by ledger code, not a numeric ledger id. The
	// "ledger_id" column is NOT NULL and is a real foreign key elsewhere in
	// this codebase (see TestUpsertBatch_TypedFailureDoesNotStrandBalanceGeneric,
	// which intentionally relies on this constraint firing for resources with
	// no resolvable ledger), so prefer resolving it from the already-synced
	// ledger table by code. `sync`'s resources run concurrently (confirmed
	// against a live account — "ledger" and "ledger-balances" progress events
	// interleave, no ordering guarantee), so this lookup can legitimately miss
	// even on a full sync if ledger-balances processes a code before ledger
	// commits it. Falling back to the balance's own resolved id (the code)
	// keeps the NOT NULL constraint satisfied without stranding every balance
	// row on a sync-order race; nothing in this codebase joins balance.ledger_id
	// against ledger.id (reports extract the code straight from balance.data).
	ledgerID := lookupFieldValue(obj, "ledger_id")
	hasCode := false
	if ledgerID == nil {
		if code := lookupFieldValue(obj, "code"); code != nil {
			hasCode = true
			var resolvedID string
			if err := tx.QueryRow(`SELECT id FROM ledger WHERE code = ?`, ResourceIDString(code)).Scan(&resolvedID); err == nil {
				ledgerID = resolvedID
			}
		}
	}
	if ledgerID == nil && hasCode {
		ledgerID = id
	}
	if ledgerID == nil {
		return fmt.Errorf("insert into balance: no ledger_id on the balance record and no code to fall back on")
	}
	if _, err := tx.Exec(
		`INSERT INTO "balance" ("id", "ledger_id", "data", "synced_at")
		 VALUES (?, ?, ?, ?)
		 ON CONFLICT("id") DO UPDATE SET "ledger_id" = excluded."ledger_id", "data" = excluded."data", "synced_at" = excluded."synced_at"`,
		id,
		ledgerID,
		string(data),
		time.Now().UTC().Format(time.RFC3339),
	); err != nil {
		return fmt.Errorf("insert into balance: %w", err)
	}

	return nil
}

// UpsertBalance inserts or updates a balance record with domain-specific columns.
func (s *Store) UpsertBalance(data json.RawMessage) error {
	obj, err := DecodeJSONObject(data)
	if err != nil {
		return fmt.Errorf("unmarshaling balance: %w", err)
	}

	// extractObjectID only checks id/Id/ID/uuid/slug/name. e-Boekhouden's
	// balance DTO has none of those — it's keyed by "Code" (or "code" on the
	// single-ledger-balance endpoint) instead. Known generator gap: the
	// sync-level extractID() fallback list includes "code" but the
	// store-level extractObjectID() used by every typed Upsert* function does
	// not, so any resource keyed by a non-id field silently fails here unless
	// worked around per-resource like this.
	id := extractObjectID(obj)
	if id == "" {
		if code := lookupFieldValue(obj, "code"); code != nil {
			id = ResourceIDString(code)
		}
	}
	if id == "" {
		return fmt.Errorf("missing id for balance")
	}

	s.writeMu.Lock()
	defer s.writeMu.Unlock()
	tx, err := s.db.Begin()
	if err != nil {
		return err
	}
	defer tx.Rollback()

	if err := s.upsertGenericResourceTx(tx, "balance", id, data); err != nil {
		return err
	}
	if err := s.upsertBalanceTx(tx, id, obj, data); err != nil {
		return err
	}

	return tx.Commit()
}

